/* =============================================================================
   010_dimensions.sql: dimension and configuration tables (schema dw)
   Data dictionary §3. Every table carries the lineage columns (§1).
   Special members -1 Unknown / -2 Not applicable are seeded in 011 (D11).
   Allowed-value CHECKs mirror the data dictionary; the ETL validator enforces
   the same lists earlier, so a CHECK failure here means a validator bug.
   ============================================================================= */
SET NOCOUNT ON;
GO

/* --- dim_calendar (§3.1): generated by etl.usp_build_calendar -------------- */
IF OBJECT_ID(N'dw.dim_calendar', N'U') IS NULL
CREATE TABLE dw.dim_calendar (
    date_key          INT          NOT NULL CONSTRAINT pk_dim_calendar PRIMARY KEY,   -- yyyymmdd
    [date]            DATE         NOT NULL CONSTRAINT uq_dim_calendar_date UNIQUE,
    [year]            SMALLINT     NOT NULL,
    [quarter]         TINYINT      NOT NULL CONSTRAINT ck_dim_calendar_quarter CHECK ([quarter] BETWEEN 1 AND 4),
    quarter_label     CHAR(7)      NOT NULL,          -- 2025-Q1
    [month]           TINYINT      NOT NULL CONSTRAINT ck_dim_calendar_month CHECK ([month] BETWEEN 1 AND 12),
    month_name        VARCHAR(10)  NOT NULL,
    month_short       CHAR(3)      NOT NULL,
    year_month        CHAR(7)      NOT NULL,          -- 2025-03
    month_start_date  DATE         NOT NULL,
    iso_year          SMALLINT     NOT NULL,
    iso_week          TINYINT      NOT NULL CONSTRAINT ck_dim_calendar_iso_week CHECK (iso_week BETWEEN 1 AND 53),
    day_of_week       TINYINT      NOT NULL CONSTRAINT ck_dim_calendar_dow CHECK (day_of_week BETWEEN 1 AND 7), -- 1 = Monday
    day_name          VARCHAR(10)  NOT NULL,
    is_weekend        BIT          NOT NULL,
    is_plant_holiday  BIT          NOT NULL,
    is_working_day    BIT          NOT NULL,
    etl_run_id        INT           NOT NULL CONSTRAINT fk_dim_calendar_run REFERENCES [audit].etl_run (etl_run_id),
    source_file       NVARCHAR(260) NOT NULL,
    loaded_at_utc     DATETIME2(0)  NOT NULL CONSTRAINT df_dim_calendar_loaded DEFAULT SYSUTCDATETIME(),
    updated_at_utc    DATETIME2(0)  NULL,
    CONSTRAINT ck_dim_calendar_key CHECK (date_key = YEAR([date]) * 10000 + MONTH([date]) * 100 + DAY([date])),
    CONSTRAINT ck_dim_calendar_working CHECK (is_working_day = CASE WHEN is_weekend = 0 AND is_plant_holiday = 0 THEN 1 ELSE 0 END)
);
GO

/* --- plant_holiday: feeds dim_calendar.is_plant_holiday (D17) --------------
   Synchronised from config/settings.toml [calendar] by python -m etl.deploy,
   so settings.toml stays the single source of truth for holidays.            */
IF OBJECT_ID(N'dw.plant_holiday', N'U') IS NULL
CREATE TABLE dw.plant_holiday (
    holiday_date    DATE          NOT NULL CONSTRAINT pk_plant_holiday PRIMARY KEY,
    holiday_type    VARCHAR(10)   NOT NULL CONSTRAINT ck_plant_holiday_type CHECK (holiday_type IN ('Annual', 'Shutdown')),
    etl_run_id      INT           NOT NULL CONSTRAINT fk_plant_holiday_run REFERENCES [audit].etl_run (etl_run_id),
    source_file     NVARCHAR(260) NOT NULL,
    loaded_at_utc   DATETIME2(0)  NOT NULL CONSTRAINT df_plant_holiday_loaded DEFAULT SYSUTCDATETIME(),
    updated_at_utc  DATETIME2(0)  NULL
);
GO

/* --- dim_shift (§3.2): reference data, seeded in 011 ----------------------- */
IF OBJECT_ID(N'dw.dim_shift', N'U') IS NULL
CREATE TABLE dw.dim_shift (
    shift_key         INT IDENTITY(1,1) NOT NULL CONSTRAINT pk_dim_shift PRIMARY KEY,
    shift_code        VARCHAR(5)    NOT NULL CONSTRAINT uq_dim_shift_code UNIQUE,
    shift_name        NVARCHAR(30)  NOT NULL,
    start_time        TIME(0)       NOT NULL,
    end_time          TIME(0)       NOT NULL,
    crosses_midnight  BIT           NOT NULL,
    sort_order        TINYINT       NOT NULL,
    etl_run_id        INT           NOT NULL CONSTRAINT fk_dim_shift_run REFERENCES [audit].etl_run (etl_run_id),
    source_file       NVARCHAR(260) NOT NULL,
    loaded_at_utc     DATETIME2(0)  NOT NULL CONSTRAINT df_dim_shift_loaded DEFAULT SYSUTCDATETIME(),
    updated_at_utc    DATETIME2(0)  NULL,
    CONSTRAINT ck_dim_shift_midnight CHECK (crosses_midnight = CASE WHEN end_time < start_time THEN 1 ELSE 0 END)
);
GO

/* --- dim_production_line (§3.3) -------------------------------------------- */
IF OBJECT_ID(N'dw.dim_production_line', N'U') IS NULL
CREATE TABLE dw.dim_production_line (
    line_key        INT IDENTITY(1,1) NOT NULL CONSTRAINT pk_dim_production_line PRIMARY KEY,
    line_code       VARCHAR(5)    NOT NULL CONSTRAINT uq_dim_production_line_code UNIQUE,
    line_name       NVARCHAR(60)  NOT NULL,
    process_type    VARCHAR(30)   NOT NULL CONSTRAINT ck_dim_production_line_process
                                           CHECK (process_type IN ('Injection Moulding', 'Painting', 'Assembly', 'Welding',
                                                                   'Unknown', 'Not applicable')),
    area            NVARCHAR(30)  NOT NULL,
    is_active       BIT           NOT NULL,
    etl_run_id      INT           NOT NULL CONSTRAINT fk_dim_production_line_run REFERENCES [audit].etl_run (etl_run_id),
    source_file     NVARCHAR(260) NOT NULL,
    loaded_at_utc   DATETIME2(0)  NOT NULL CONSTRAINT df_dim_production_line_loaded DEFAULT SYSUTCDATETIME(),
    updated_at_utc  DATETIME2(0)  NULL
);
GO

/* --- dim_vehicle_program (§3.4) -------------------------------------------- */
IF OBJECT_ID(N'dw.dim_vehicle_program', N'U') IS NULL
CREATE TABLE dw.dim_vehicle_program (
    program_key      INT IDENTITY(1,1) NOT NULL CONSTRAINT pk_dim_vehicle_program PRIMARY KEY,
    program_code     VARCHAR(15)   NOT NULL CONSTRAINT uq_dim_vehicle_program_code UNIQUE,
    program_name     NVARCHAR(60)  NOT NULL,
    oem_customer     NVARCHAR(60)  NOT NULL,      -- fictional OEM names only
    vehicle_segment  VARCHAR(20)   NOT NULL,
    sop_date         DATE          NOT NULL,
    eop_date         DATE          NULL,          -- NULL = still running
    etl_run_id       INT           NOT NULL CONSTRAINT fk_dim_vehicle_program_run REFERENCES [audit].etl_run (etl_run_id),
    source_file      NVARCHAR(260) NOT NULL,
    loaded_at_utc    DATETIME2(0)  NOT NULL CONSTRAINT df_dim_vehicle_program_loaded DEFAULT SYSUTCDATETIME(),
    updated_at_utc   DATETIME2(0)  NULL,
    CONSTRAINT ck_dim_vehicle_program_dates CHECK (eop_date IS NULL OR eop_date > sop_date)
);
GO

/* --- dim_part (§3.5): Type 1; cost is snapshotted into facts (D7) ----------- */
IF OBJECT_ID(N'dw.dim_part', N'U') IS NULL
CREATE TABLE dw.dim_part (
    part_key                INT IDENTITY(1,1) NOT NULL CONSTRAINT pk_dim_part PRIMARY KEY,
    part_number             VARCHAR(20)    NOT NULL CONSTRAINT uq_dim_part_number UNIQUE,
    part_name               NVARCHAR(100)  NOT NULL,
    component_type          VARCHAR(30)    NOT NULL,
    program_key             INT            NOT NULL CONSTRAINT fk_dim_part_program REFERENCES dw.dim_vehicle_program (program_key),
    primary_line_key        INT            NOT NULL CONSTRAINT fk_dim_part_line    REFERENCES dw.dim_production_line (line_key),
    standard_unit_cost_eur  DECIMAL(18,4)  NOT NULL,
    opportunities_per_unit  SMALLINT       NOT NULL,
    is_active               BIT            NOT NULL,
    etl_run_id              INT            NOT NULL CONSTRAINT fk_dim_part_run REFERENCES [audit].etl_run (etl_run_id),
    source_file             NVARCHAR(260)  NOT NULL,
    loaded_at_utc           DATETIME2(0)   NOT NULL CONSTRAINT df_dim_part_loaded DEFAULT SYSUTCDATETIME(),
    updated_at_utc          DATETIME2(0)   NULL,
    -- Special members (key < 0) carry cost 0: scrap of an unknown part is costed at 0 and flagged by VR-GEN-06
    CONSTRAINT ck_dim_part_cost          CHECK (standard_unit_cost_eur > 0 OR (part_key < 0 AND standard_unit_cost_eur = 0)),
    CONSTRAINT ck_dim_part_opportunities CHECK (opportunities_per_unit > 0)
);
GO

/* --- dim_defect_type (§3.6) ------------------------------------------------ */
IF OBJECT_ID(N'dw.dim_defect_type', N'U') IS NULL
CREATE TABLE dw.dim_defect_type (
    defect_type_key  INT IDENTITY(1,1) NOT NULL CONSTRAINT pk_dim_defect_type PRIMARY KEY,
    defect_code      VARCHAR(10)   NOT NULL CONSTRAINT uq_dim_defect_type_code UNIQUE,
    defect_name      NVARCHAR(80)  NOT NULL,
    defect_category  VARCHAR(20)   NOT NULL CONSTRAINT ck_dim_defect_type_category
                                            CHECK (defect_category IN ('Dimensional', 'Surface', 'Assembly', 'Material',
                                                                       'Functional', 'Unknown', 'Not applicable')),
    severity         CHAR(1)       NOT NULL,      -- A critical, B major, C minor; '-' for special members
    etl_run_id       INT           NOT NULL CONSTRAINT fk_dim_defect_type_run REFERENCES [audit].etl_run (etl_run_id),
    source_file      NVARCHAR(260) NOT NULL,
    loaded_at_utc    DATETIME2(0)  NOT NULL CONSTRAINT df_dim_defect_type_loaded DEFAULT SYSUTCDATETIME(),
    updated_at_utc   DATETIME2(0)  NULL,
    CONSTRAINT ck_dim_defect_type_severity CHECK (severity IN ('A', 'B', 'C') OR (defect_type_key < 0 AND severity = '-'))
);
GO

/* --- dim_inspection_stage (§3.7): reference data, seeded in 011 ------------ */
IF OBJECT_ID(N'dw.dim_inspection_stage', N'U') IS NULL
CREATE TABLE dw.dim_inspection_stage (
    stage_key       INT IDENTITY(1,1) NOT NULL CONSTRAINT pk_dim_inspection_stage PRIMARY KEY,
    stage_code      VARCHAR(10)   NOT NULL CONSTRAINT uq_dim_inspection_stage_code UNIQUE,
    stage_name      NVARCHAR(40)  NOT NULL,
    stage_sequence  TINYINT       NOT NULL,       -- highest sequence with data = final stage of a line
    etl_run_id      INT           NOT NULL CONSTRAINT fk_dim_inspection_stage_run REFERENCES [audit].etl_run (etl_run_id),
    source_file     NVARCHAR(260) NOT NULL,
    loaded_at_utc   DATETIME2(0)  NOT NULL CONSTRAINT df_dim_inspection_stage_loaded DEFAULT SYSUTCDATETIME(),
    updated_at_utc  DATETIME2(0)  NULL
);
GO

/* --- kpi_target (§3.8): RAG thresholds, seeded in Phase 8 ------------------ */
IF OBJECT_ID(N'dw.kpi_target', N'U') IS NULL
CREATE TABLE dw.kpi_target (
    kpi_target_key  INT IDENTITY(1,1) NOT NULL CONSTRAINT pk_kpi_target PRIMARY KEY,
    kpi_code        VARCHAR(30)    NOT NULL,
    valid_from      DATE           NOT NULL,
    valid_to        DATE           NULL,          -- NULL = current
    target_value    DECIMAL(18,6)  NOT NULL,      -- ratios as fractions (0.97)
    amber_limit     DECIMAL(18,6)  NOT NULL,
    direction       VARCHAR(16)    NOT NULL CONSTRAINT ck_kpi_target_direction CHECK (direction IN ('higher_better', 'lower_better')),
    unit            VARCHAR(10)    NOT NULL CONSTRAINT ck_kpi_target_unit CHECK (unit IN ('pct', 'eur', 'days', 'count')),
    target_type     VARCHAR(15)    NOT NULL CONSTRAINT df_kpi_target_type DEFAULT 'Illustrative',
    etl_run_id      INT            NOT NULL CONSTRAINT fk_kpi_target_run REFERENCES [audit].etl_run (etl_run_id),
    source_file     NVARCHAR(260)  NOT NULL,
    loaded_at_utc   DATETIME2(0)   NOT NULL CONSTRAINT df_kpi_target_loaded DEFAULT SYSUTCDATETIME(),
    updated_at_utc  DATETIME2(0)   NULL,
    CONSTRAINT uq_kpi_target_code_from UNIQUE (kpi_code, valid_from),
    CONSTRAINT ck_kpi_target_validity  CHECK (valid_to IS NULL OR valid_to >= valid_from),
    -- The amber band lies on the "worse" side of the target
    CONSTRAINT ck_kpi_target_amber CHECK ((direction = 'higher_better' AND amber_limit <= target_value)
                                       OR (direction = 'lower_better'  AND amber_limit >= target_value))
);
